caseTriggers.ACTION_STATEMENT:
BEGIN

    DECLARE msg char(250);
    DECLARE isUnique boolean;
    DECLARE maxNumber INT;
    DECLARE caseTypeName char(100);
    SET isUnique = (SELECT IsUniquePerMilestone FROM CaseTypes WHERE Id=NEW.TypeId);
    SET caseTypeName = (SELECT Name FROM CaseTypes WHERE Id=new.TypeId);
    IF isUnique AND new.name != '' THEN
        SET msg = CONCAT('NewCaseHandler Trigger -> uniqueCaseTypeHandlerError: \nSprawa typu ', caseTypeName, ' nie może mieć nazwy " ',new.name, '"\nZostaw pole nazwy sprawy puste i spróbuj ponownie.');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
    END IF;


	IF NOT isUnique THEN
	    SET maxNumber = (SELECT MAX(Number) FROM Cases WHERE MilestoneId=new.MilestoneId AND TypeId=new.TypeId);
        IF maxNumber IS NULL THEN
        	SET maxNumber = 0;
        END IF;
    	SET NEW.Number = (SELECT maxNumber + 1);
	END IF;
END

